using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Npgsql;
using SmartRent.Api.Common;
namespace SmartRent.Api.Features.Contracts;

[ApiController, Route("api/v1/contracts")]
public sealed class ContractsController(NpgsqlDataSource db) : LeasingController(db)
{
    [HttpGet] public async Task<IActionResult> List([FromQuery] Guid? tenantId, [FromQuery] Guid? roomId, [FromQuery] int page = 1, [FromQuery] int pageSize = 30, CancellationToken ct = default) { try { var (c, t, _) = await BeginAsync(true, ct); await using (c) await using (t) { page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 200); var rows = await JsonRowsAsync(c, t, $"select {ContractSql.Json("c")} from contracts c join users u on u.id=c.user_id join rooms r on r.id=c.room_id join properties p on p.id=r.property_id where (@tenant is null or c.user_id=@tenant) and (@room is null or c.room_id=@room) order by c.created_at desc offset @skip limit @take", ct, P("tenant", tenantId), P("room", roomId), P("skip", (page - 1) * pageSize), P("take", pageSize)); await t.RollbackAsync(ct); return Ok(new { items = rows, page, pageSize }); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
    [HttpGet("{id:guid}")] public async Task<IActionResult> Get(Guid id, CancellationToken ct) { try { var (c, t, _) = await BeginAsync(true, ct); await using (c) await using (t) { var json = await ScalarStringAsync(c, t, $"select {ContractSql.Json("c", true)} from contracts c join users u on u.id=c.user_id join rooms r on r.id=c.room_id join properties p on p.id=r.property_id where c.id=@id", ct, P("id", id)); await t.RollbackAsync(ct); return json is null ? NotFound() : Content(json, "application/json"); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
    [HttpPost("{id:guid}/attachments")] public Task<IActionResult> AddAttachment(Guid id, [FromBody] JsonElement body, CancellationToken ct) => Attachment(id, body.Guid("fileId"), true, ct);
    [HttpDelete("{id:guid}/attachments/{fileId:guid}")] public Task<IActionResult> RemoveAttachment(Guid id, Guid fileId, CancellationToken ct) => Attachment(id, fileId, false, ct);
    private async Task<IActionResult> Attachment(Guid id, Guid? fileId, bool add, CancellationToken ct) { if (fileId is null) return BadRequest(new { code = "file_required", message = "Cần chọn tệp." }); try { var (c, t, _) = await BeginAsync(true, ct); await using (c) await using (t) { var json = await ScalarStringAsync(c, t, $"update contracts set attachments=(case when @add then attachments||jsonb_build_array(@file::text) else (select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(attachments)x where x<>to_jsonb(@file::text)) end) where id=@id returning {ContractSql.Json("contracts", true)}", ct, P("id", id), P("file", fileId.ToString()), P("add", add)); if (json is null) { await t.RollbackAsync(ct); return NotFound(); } await CommitAsync(t, ct); return Content(json, "application/json"); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
    [HttpPost("{id:guid}/versions")] public Task<IActionResult> CreateVersion(Guid id, [FromBody] JsonElement body, CancellationToken ct) => SaveVersion(id, null, body, ct);
    [HttpPut("{id:guid}/versions/{versionId:guid}")] public Task<IActionResult> UpdateVersion(Guid id, Guid versionId, [FromBody] JsonElement body, CancellationToken ct) => SaveVersion(id, versionId, body, ct);
    private async Task<IActionResult> SaveVersion(Guid id, Guid? versionId, JsonElement body, CancellationToken ct) { try { var (c, t, _) = await BeginAsync(true, ct); await using (c) await using (t) { var old = await ScalarStringAsync(c, t, "select versions::text from contracts where id=@id for update", ct, P("id", id)); if (old is null) { await t.RollbackAsync(ct); return NotFound(); } var versions = JsonDocument.Parse(old).RootElement; var number = 1; if (versions.GetArrayLength() > 0) number = versions.EnumerateArray().Max(x => x.GetProperty("versionNo").GetInt32()) + 1; var vid = versionId ?? Guid.NewGuid(); var version = ContractSql.Version(body, vid, number, null, null); var json = await ScalarStringAsync(c, t, """update contracts set versions=(select coalesce(jsonb_agg(case when x->>'id'=@versionId then @version::jsonb else x end),'[]') from jsonb_array_elements(versions)x) where id=@id and (@exists or not exists(select 1 from jsonb_array_elements(versions)x where x->>'id'=@versionId)) returning versions::text""", ct, P("id", id), P("versionId", vid.ToString()), P("version", version), P("exists", versionId is not null)); if (versionId is null) json = await ScalarStringAsync(c, t, "update contracts set versions=versions||jsonb_build_array(@version::jsonb) where id=@id returning versions::text", ct, P("id", id), P("version", version)); await CommitAsync(t, ct); return Content(json!, "application/json"); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
    [HttpPost("{id:guid}/versions/{versionId:guid}/sign")] public async Task<IActionResult> Sign(Guid id, Guid versionId, [FromBody] JsonElement body, CancellationToken ct) { var file = body.Guid("signedFileId"); if (file is null) return BadRequest(new { code = "signed_file_required", message = "Cần bản hợp đồng đã ký." }); try { var (c, t, actor) = await BeginAsync(true, ct); await using (c) await using (t) { var json = await ScalarStringAsync(c, t, """update contracts set versions=(select jsonb_agg(case when x->>'id'=@version then jsonb_set(jsonb_set(jsonb_set(x,'{signedAt}',to_jsonb(@at::timestamptz)),'{signedBy}',to_jsonb(@actor::text)),'{fileIds}',jsonb_build_array(@file::text)) else x end) from jsonb_array_elements(versions)x) where id=@id returning """ + ContractSql.Json("contracts", true), ct, P("id", id), P("version", versionId.ToString()), P("at", body.String("signedAt") ?? DateTimeOffset.UtcNow.ToString("O")), P("actor", actor.ToString()), P("file", file.ToString())); if (json is null) { await t.RollbackAsync(ct); return NotFound(); } await CommitAsync(t, ct); return Content(json, "application/json"); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
    [HttpPost("{id:guid}/archive")] public async Task<IActionResult> Archive(Guid id, CancellationToken ct) { try { var (c, t, _) = await BeginAsync(true, ct); await using (c) await using (t) { var json = await ScalarStringAsync(c, t, "update contracts set archived_at=now() where id=@id and status in ('ended','cancelled') returning id::text", ct, P("id", id)); if (json is null) { await t.RollbackAsync(ct); return NotFound(); } await CommitAsync(t, ct); return Ok(new { id, archivedAt = DateTimeOffset.UtcNow }); } } catch (LeaseHttpException e) { return LeaseProblem(e); } catch (PostgresException e) { return DatabaseProblem(e); } }
}

internal static class ContractSql
{
    public static string Json(string c, bool detail = false) => $"""jsonb_build_object('id',{c}.id,'contractId',{c}.id,'tenancyId',{c}.id,'code',{c}.code,'status',{c}.status,'onboardingMode',{c}.onboarding_mode,'startsOn',{c}.starts_on,'endsOn',{c}.ends_on,'moveInOn',{c}.move_in_on,'moveOutOn',{c}.move_out_on,'requiredDeposit',{c}.required_deposit,'archivedAt',{c}.archived_at,'tenant',jsonb_build_object('id',u.id,'fullName',u.display_name,'code',u.code,'phone',u.phone,'email',u.email),'room',jsonb_build_object('id',r.id,'code',r.code,'name',r.name,'propertyId',p.id,'propertyName',p.name),'versions',{c}.versions,'attachments',{c}.attachments,'occupants',{c}.occupants,'initialReadings',{c}.initial_readings,'finalReadings',{c}.final_readings{(detail ? $",'checkinHandover',{c}.checkin_handover,'checkoutHandover',{c}.checkout_handover,'checkoutSummary',{c}.checkout_summary,'onboardingGaps',{c}.onboarding_gaps,'endedReason',{c}.ended_reason,'remainingDebtReason',{c}.remaining_debt_reason" : "")})""";
    public static string Version(JsonElement b, Guid id, int number, Guid? signer, string? at) { var rates = b.ValueOr("rates", JsonInput.EmptyArray).GetRawText(); return JsonSerializer.Serialize(new { id, versionNo = number, effectiveFrom = b.String("effectiveFrom") ?? b.String("startsOn"), endsOn = b.String("endsOn"), requiredDeposit = b.Decimal("requiredDeposit") ?? 0, invoiceDay = b.Decimal("invoiceDay") ?? 1, dueAfterDays = b.Decimal("dueAfterDays") ?? 5, prorationPolicy = b.String("prorationPolicy") ?? "actual_days", termsText = b.String("termsText") ?? "", changeReason = b.String("changeReason"), signedAt = at, signedBy = signer, fileIds = Array.Empty<string>(), partiesSnapshot = new { }, rates = JsonDocument.Parse(rates).RootElement }); }
}
